custom_overrides:
/* =========================================================
   MARSOL TECHNOLOGIES
   CLEAN PROFESSIONAL WEBSITE THEME
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */
/* =========================================================
   MARSOL - REMOVE EXCESSIVE PAGE BUILDER SPACING
   ========================================================= */

/* Main website page */
.page-content-wrapper {
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    min-height: auto !important;
}

/* All website sections */
.page-content-wrapper section {
    padding-top: 25px !important;
    padding-bottom: 25px !important;
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}

/* Frappe section padding */
.page-content-wrapper .section-padding {
    padding-top: 25px !important;
    padding-bottom: 25px !important;
}

/* Smaller predefined section sizes */
.page-content-wrapper .section-md {
    padding-top: 25px !important;
    padding-bottom: 25px !important;
}

.page-content-wrapper .section-sm {
    padding-top: 15px !important;
    padding-bottom: 15px !important;
}

/* Bootstrap vertical spacing */
.page-content-wrapper .my-5,
.page-content-wrapper .my-4,
.page-content-wrapper .my-3 {
    margin-top: 20px !important;
    margin-bottom: 20px !important;
}

.page-content-wrapper .py-5,
.page-content-wrapper .py-4,
.page-content-wrapper .py-3 {
    padding-top: 20px !important;
    padding-bottom: 20px !important;
}

/* Hero */
.page-content-wrapper .hero {
    margin-top: 30px !important;
    margin-bottom: 30px !important;
}

/* Don't add spacing immediately after hero */
.page-content-wrapper .hero + section {
    margin-top: 0 !important;
    padding-top: 20px !important;
}


/* =========================================================
   REMOVE EMPTY / EXCESSIVE ROW SPACE
   ========================================================= */

.page-content-wrapper .row {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}


/* =========================================================
   FOOTER
   ========================================================= */

.web-footer {
    margin-top: 20px !important;
    padding-top: 25px !important;
    padding-bottom: 18px !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    .page-content-wrapper section {
        padding-top: 20px !important;
        padding-bottom: 20px !important;
    }

    .page-content-wrapper .section-padding {
        padding-top: 20px !important;
        padding-bottom: 20px !important;
    }

    .page-content-wrapper .hero {
        margin-top: 20px !important;
        margin-bottom: 25px !important;
    }
}

body {
    background: #f8fafc !important;
    color: #111827 !important;
    font-family: "Inter", sans-serif !important;
}

.container {
    max-width: 1180px !important;
}

a {
    transition: color 0.2s ease !important;
}

a:hover {
    color: #e85d04 !important;
}


/* =========================================================
   NAVBAR
   ========================================================= */

.navbar {
    background: #ffffff !important;
    border-bottom: 1px solid #e5e7eb !important;
    min-height: 70px !important;
    box-shadow: 0 2px 10px rgba(15, 23, 42, 0.04) !important;
}

.navbar a {
    color: #111827 !important;
    font-weight: 500 !important;
}

.navbar a:hover {
    color: #e85d04 !important;
}

.navbar .nav-link {
    padding-left: 14px !important;
    padding-right: 14px !important;
}

/* Active page */

.navbar .nav-link.active,
.navbar .nav-link.active:hover,
.navbar .nav-link.active:focus {
    border-bottom: none !important;
    box-shadow: none !important;
    background: transparent !important;
}

.navbar .nav-link.active::after {
    content: "";
    display: block;
    width: 28px;
    height: 2px;
    background: #e85d04 !important;
    margin: 6px auto 0;
    border-radius: 2px;
}


/* =========================================================
   BRAND
   ========================================================= */

.marsol-brand {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    text-decoration: none !important;
    line-height: 1 !important;
}

.marsol-brand-name {
    font-size: 20px !important;
    font-weight: 800 !important;
    letter-spacing: 1px !important;
    color: #111827 !important;
}

.marsol-brand-subtitle {
    font-size: 10px !important;
    font-weight: 600 !important;
    letter-spacing: 1.8px !important;
    color: #e85d04 !important;
}


/* =========================================================
   HEADINGS
   ========================================================= */

h1,
h2,
h3,
h4 {
    color: #111827 !important;
    font-weight: 700 !important;
}

h1 {
    letter-spacing: -0.8px !important;
}

h2 {
    letter-spacing: -0.4px !important;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.btn-primary {
    background: #e85d04 !important;
    border-color: #e85d04 !important;
    color: #ffffff !important;
    border-radius: 8px !important;
    font-weight: 600 !important;
    padding: 10px 22px !important;
}

.btn-primary:hover {
    background: #c94d03 !important;
    border-color: #c94d03 !important;
    transform: translateY(-1px);
}

.btn-secondary {
    border-radius: 8px !important;
    font-weight: 600 !important;
}


/* =========================================================
   CARDS
   ========================================================= */

.card {
    background: #ffffff !important;
    border: 1px solid #e5e7eb !important;
    border-radius: 12px !important;
    transition: all 0.25s ease !important;
}

.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08) !important;
}


/* =========================================================
   HERO
   ========================================================= */

.hero {
    max-width: 1100px !important;

    margin: 35px auto 55px !important;

    padding: 55px 60px !important;

    background: linear-gradient(
        135deg,
        #fffaf3 0%,
        #ffffff 48%,
        #f1f5ff 100%
    ) !important;

    border-radius: 16px !important;

    border: 1px solid #eef0f4 !important;

    box-shadow:
        0 12px 35px rgba(15, 23, 42, 0.06) !important;
}


/* Hero heading */

.hero h1 {
    max-width: 720px !important;

    margin-top: 0 !important;
    margin-bottom: 18px !important;

    color: #111827 !important;

    font-size: 48px !important;
    line-height: 1.08 !important;

    font-weight: 800 !important;

    letter-spacing: -1px !important;
}


/* Hero paragraph */

.hero p {
    max-width: 680px !important;

    margin-top: 0 !important;
    margin-bottom: 28px !important;

    color: #64748b !important;

    font-size: 17px !important;
    line-height: 1.7 !important;
}


/* Hero primary button */

.hero .btn-primary,
.hero a.btn-primary {
    background: #111827 !important;
    border: 1px solid #111827 !important;

    color: #ffffff !important;

    padding: 13px 24px !important;

    border-radius: 7px !important;

    font-weight: 600 !important;
}

.hero .btn-primary:hover,
.hero a.btn-primary:hover {
    background: #e85d04 !important;
    border-color: #e85d04 !important;
}


/* Hero secondary button */

.hero .btn-secondary,
.hero a.btn-secondary {
    background: #ffffff !important;

    border: 1px solid #e5e7eb !important;

    color: #111827 !important;

    padding: 13px 24px !important;

    border-radius: 7px !important;

    font-weight: 600 !important;
}

.hero .btn-secondary:hover,
.hero a.btn-secondary:hover {
    border-color: #e85d04 !important;
    color: #e85d04 !important;
}


/* =========================================================
   WEB PAGE BUILDER SPACING
   ========================================================= */

/* Main website content */

.web-page-content {
    padding-top: 0 !important;
    padding-bottom: 0 !important;
}

/* Generic sections */

.web-page-content section {
    margin-top: 0 !important;
    margin-bottom: 25px !important;
    padding-top: 25px !important;
    padding-bottom: 25px !important;
}

/* Page sections */

.web-page-content .page-section {
    margin-top: 0 !important;
    margin-bottom: 25px !important;

    padding-top: 25px !important;
    padding-bottom: 25px !important;
}

/* Bootstrap spacing classes that can create huge gaps */

.web-page-content .my-5 {
    margin-top: 25px !important;
    margin-bottom: 25px !important;
}

.web-page-content .py-5 {
    padding-top: 25px !important;
    padding-bottom: 25px !important;
}


/* =========================================================
   FOOTER
   ========================================================= */

.footer {
    background: #ffffff !important;
    color: #64748b !important;
    border-top: 1px solid #e5e7eb !important;
}

.footer a {
    color: #475569 !important;
}

.footer a:hover {
    color: #e85d04 !important;
}

.web-footer {
    padding: 25px 0 18px !important;
    font-size: 13px !important;
}

.web-footer .footer-links {
    margin-bottom: 12px !important;
    padding: 0 !important;
}

.web-footer .footer-links a {
    margin-right: 18px !important;
}

.web-footer .footer-info {
    margin-top: 10px !important;
    padding-top: 12px !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

    .container {
        padding-left: 20px !important;
        padding-right: 20px !important;
    }

    .hero {
        margin: 25px 15px 35px !important;
        padding: 40px 25px !important;
    }

    .hero h1 {
        font-size: 36px !important;
    }

    .hero p {
        font-size: 15px !important;
    }

    .web-page-content section,
    .web-page-content .page-section {
        padding-top: 20px !important;
        padding-bottom: 20px !important;
        margin-bottom: 15px !important;
    }

    h1 {
        font-size: 36px !important;
    }

    h2 {
        font-size: 28px !important;
    }
}

